func pruneOptionalEmptyMongoFields(doc bson.M) {
	for _, opt := range optionalNullableFields {
		camelKey, snakeKey := opt[0], opt[1]
		if sv, hasSnake := doc[snakeKey]; hasSnake {
			if cv, hasCamel := doc[camelKey]; !hasCamel || isNilOrBlankBSONVal(cv) {
				doc[camelKey] = sv
			}
			delete(doc, snakeKey)
		}
