			delete(doc, camelKey)
		}
	}
}

func isNilOrBlankBSONVal(v any) bool {
	if v == nil {
		return true
	}
	if s, ok := v.(string); ok {
		return strings.TrimSpace(s) == ""
	}
	return false
}

